using LoomTerminal.Core.Services;

namespace LoomTerminal.Core.Tests.Conformance;

public sealed class RecordedConformanceTests
{
    private static string RecordedFolder => Path.Combine(AppContext.BaseDirectory, "Conformance", "Fixtures", "recorded");

    public static IEnumerable<object[]> RecordingNames() =>
        Directory.GetFiles(RecordedFolder, "*.vtrec")
            .Select(path => Path.GetFileNameWithoutExtension(path))
            .Order(StringComparer.Ordinal)
            .Select(name => new object[] { name });

    // The expected JSON is generated by tools/xterm-oracle with xterm.js itself, with the ConPTY options VIGO uses.
    [Theory]
    [MemberData(nameof(RecordingNames))]
    public void Recording_matches_xterm_js(string name)
    {
        FixtureScript script = FixtureReader.ReadRecording(File.ReadAllText(Path.Combine(RecordedFolder, name + ".vtrec")));
        string expected = ScreenSnapshotJsonContext.Normalize(File.ReadAllText(Path.Combine(RecordedFolder, name + ".json")));

        ScreenSnapshot actual = FixtureReader.Replay(script, new WindowsPtyOptions("conpty", 22631));

        Assert.Equal(expected, ScreenSnapshotJsonContext.ToJson(actual));
    }
}
